// Persamaan (1) of the proposal, ported from lib/logic/match_score.dart for the team scripts (notify-new-jobs).
// Match Score = 100 × (0,50·Sw + 0,15·St + 0,15·Sp + 0,10·Se + 0,10·Sl)
// backend/test/match-score.test.ts checks it against test/fixtures/match_cases.json, generated by the Dart code.

export type EduLevel = 'smaSmk' | 'd3' | 's1';
export type WorkMode = 'kantor' | 'hybrid' | 'remote';

export interface Job {
  wajib: string[];
  tambahan: string[];
  eduMin: EduLevel;
  /** Accepted majors; ['Semua'] means any major. */
  eduFields: string[];
  expYears: number;
  field: string;
  city: string;
  mode: WorkMode;
}

export interface Experience {
  type: 'magang' | 'organisasi' | 'kerja';
  months: number;
  field: string;
}

export interface Profile {
  level: EduLevel;
  major: string;
  city: string;
  modes: WorkMode[];
  skills: string[];
  exps: Experience[];
}

/** Job city for programmes that place hires nationwide; matches every home city (same as the app). */
export const ANY_CITY = 'Seluruh Indonesia';

const rank: Record<EduLevel, number> = { smaSmk: 1, d3: 2, s1: 3 };

export function matchScore(job: Job, p: Profile): number {
  const has = (s: string) => p.skills.includes(s);
  const sw = job.wajib.filter(has).length / job.wajib.length;
  const st = job.tambahan.filter(has).length / job.tambahan.length;

  const levelOk = rank[p.level] >= rank[job.eduMin];
  const fieldOk = job.eduFields.includes('Semua') || job.eduFields.includes(p.major);
  const sp = levelOk && fieldOk ? 1 : levelOk || fieldOk ? 0.5 : 0;

  // Internships and organisations count half; 1 when the job needs no experience.
  let se = 1;
  if (job.expYears > 0) {
    const relevant = p.exps
      .filter((e) => e.field === job.field)
      .reduce((a, e) => a + (e.type === 'kerja' ? e.months : e.months / 2), 0);
    se = Math.min(Math.max(relevant / (job.expYears * 12), 0), 1);
  }

  // "Seluruh Indonesia": the programme places hires nationwide, so any home city matches.
  const cityOk = job.mode === 'remote' || job.city === ANY_CITY || job.city === p.city;
  const modeOk = p.modes.includes(job.mode);
  const sl = cityOk && modeOk ? 1 : cityOk || modeOk ? 0.5 : 0;

  return 100 * (0.5 * sw + 0.15 * st + 0.15 * sp + 0.1 * se + 0.1 * sl);
}

/** "92,5": one decimal at most, Indonesian decimal comma (same as the app). */
export function formatScore(n: number): string {
  const r = Math.round(n * 10) / 10;
  return (Number.isInteger(r) ? String(r) : r.toFixed(1)).replace('.', ',');
}
